package cn.iocoder.yudao.module.amazon.controller.admin.productfees;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.amazon.controller.admin.products.vo.AmazonProductsReqVO; import cn.iocoder.yudao.module.amazon.service.productfees.AmazonProductFeesService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
/** Amazon Product Fees 管理接口。 */
@Tag(name="管理后台 - Amazon Product Fees") @RestController @RequestMapping("/amazon/product-fees") public class AmazonProductFeesController { @Resource private AmazonProductFeesService service; @PostMapping("/by-sku") @PreAuthorize("@ss.hasPermission('amazon:product-fees:query')") public CommonResult<Map<String,Object>> sku(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.sku(r));} @PostMapping("/by-asin") @PreAuthorize("@ss.hasPermission('amazon:product-fees:query')") public CommonResult<Map<String,Object>> asin(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.asin(r));} @PostMapping("/batch") @PreAuthorize("@ss.hasPermission('amazon:product-fees:query')") public CommonResult<Map<String,Object>> batch(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.batch(r));} }
